using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(UriTemplate = "config://app/settings",
    Name = "AppSettings",
    Description = "Returns current application configuration data")]
public class ConfigurationResource
{
    public Task<ReadResourceResult> ReadAsync(RequestContext<ReadResourceRequestParams> context,
        CancellationToken cancellationToken)
    {
        var config = new
        {
            Environment = "Production",
            Version = "1.0.0",
            Features = new
            {
                EnableCaching = true,
                MaxConnections = 100,
                TimeoutSeconds = 30
            }
        };

        var json = JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });

        return Task.FromResult(new ReadResourceResult
        {
            Contents =
            [
                new ResourceContents
                {
                    Uri = "config://app/settings",
                    MimeType = "application/json",
                    Text = json
                }
            ]
        });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTool
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name")]
    public static string Greet([Description("The name to greet")] string name)
    {
        return $"Hello, {name}! Welcome to the MCP HTTP server.";
    }
}

